<script setup>
import { Link, router, useForm, usePage } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import ActionIconButton from '../../Components/ActionIconButton.vue';
import AdminDataTable from '../../Components/AdminDataTable.vue';
import Modal from '../../Components/Modal.vue';
import PasswordField from '../../Components/PasswordField.vue';
import PortalLayout from '../../Layouts/PortalLayout.vue';
import SectionTitle from '../../Components/SectionTitle.vue';
import { formatPublicDate } from '../../lib/date';

const currentUser = computed(() => usePage().props.auth.user);
const props = defineProps({ users: Object, filters: Object, stats: Object });
const isSuperAdmin = computed(() => currentUser.value.role === 'super_admin');
const activeTab = computed(() => props.filters.tab || 'internal');
const formModal = ref(false);
const detailUser = ref(null);
const deleteUser = ref(null);
const deleting = ref(false);
const editingId = ref(null);
const form = useForm({ name: '', email: '', password: '', password_confirmation: '', role: 'scorekeeper', account_status: 'verified' });
const roleLabels = { admin_event: 'Admin', scorekeeper: 'Scorekeeper', sport_coordinator: 'Koordinator Cabor' };
const roleDescriptions = { admin_event: 'Operasional Admin tanpa kelola akun lain', scorekeeper: 'Input skor sesuai assignment', sport_coordinator: 'Koordinasi cabor sesuai assignment' };
const statusLabels = { verified: 'Aktif', suspended: 'Nonaktif' };
const openCreate = () => { editingId.value = null; form.reset(); form.clearErrors(); form.account_status = 'verified'; formModal.value = true; };
const openEdit = (user) => { editingId.value = user.id; form.clearErrors(); Object.assign(form, { name: user.name, email: user.email, role: user.role, account_status: user.account_status, password: '', password_confirmation: '' }); formModal.value = true; };
const save = () => form.submit(editingId.value ? 'put' : 'post', editingId.value ? `/admin/users/${editingId.value}` : '/admin/users', { preserveScroll: true, onSuccess: () => { formModal.value = false; form.reset(); } });
const canEdit = (user) => isSuperAdmin.value || (currentUser.value.role === 'admin_event' && currentUser.value.id === user.id);
const canDelete = (user) => isSuperAdmin.value && currentUser.value.id !== user.id;
const canToggleStatus = (user) => isSuperAdmin.value && currentUser.value.id !== user.id && user.role !== 'pd_admin';
const remove = () => { if (!deleteUser.value) return; deleting.value = true; router.delete(`/admin/users/${deleteUser.value.id}`, { preserveScroll: true, onSuccess: () => { deleteUser.value = null; }, onFinish: () => { deleting.value = false; } }); };
const toggleStatus = (user) => router.post(`/admin/users/${user.id}/toggle-status`, {}, { preserveScroll: true });
const switchTab = (tab) => router.get('/admin/users', { tab, per_page: props.filters.per_page || 10 }, { preserveState: true, replace: true });
</script>

<template>
  <PortalLayout portal="admin">
    <div class="page-head"><SectionTitle eyebrow="Sistem" title="Pengguna" meta="Akun internal dan hak login" /></div>

    <section class="overview-card operations-overview"><div><span>Kendali Identitas</span><h2>Kelola akun, peran, dan akses login dalam satu kendali.</h2><p>Akun internal dikelola sesuai kewenangan. Pengurus Daerah tetap mengikuti alur verifikasi khusus.</p></div><dl><template v-if="activeTab === 'internal'"><div><dt>Total Internal</dt><dd>{{ stats.total }}</dd></div><div><dt>Admin</dt><dd>{{ stats.event_admins }}</dd></div><div><dt>Panitia</dt><dd>{{ stats.staff }}</dd></div></template><template v-else><div><dt>Total PD</dt><dd>{{ stats.regional }}</dd></div><div><dt>Aktif</dt><dd>{{ stats.regional_active }}</dd></div><div><dt>Tidak Aktif</dt><dd>{{ stats.regional_inactive }}</dd></div></template></dl></section>

    <nav class="operation-tabs" aria-label="Jenis pengguna"><button type="button" :class="{ active: activeTab === 'internal' }" @click="switchTab('internal')"><span>01</span><b>Admin & Panitia</b><small>Akun internal sistem</small></button><button type="button" :class="{ active: activeTab === 'regional' }" @click="switchTab('regional')"><span>02</span><b>Pengurus Daerah</b><small>Akun portal delegasi</small></button></nav>
    <section class="tab-panel"><div class="panel-heading"><div><span>Daftar Pengguna</span><h3>{{ activeTab === 'internal' ? 'Admin & Panitia' : 'Pengurus Daerah' }}</h3><p>{{ activeTab === 'internal' ? 'Kelola akun internal dan assignment operasional secara terpisah.' : 'Data akun PD ditampilkan terpisah dan perubahan status dilakukan melalui Verifikasi Pengurus Daerah.' }}</p></div><button v-if="isSuperAdmin && activeTab === 'internal'" type="button" @click="openCreate">Tambah Pengguna</button><Link v-else-if="activeTab === 'regional'" href="/admin/committee-applications">Buka Verifikasi PD</Link></div>
    <AdminDataTable :paginator="users" :filters="filters" item-label="pengguna" search-placeholder="Cari nama atau email…" :filter-options="[{ value: 'active', label: 'Aktif' }, { value: 'inactive', label: 'Tidak Aktif' }]">
      <template #default="{ rows }">
        <table><thead><tr><th>Pengguna</th><th>Peran</th><th>Akses Operasional</th><th>Status Login</th><th>Dibuat</th><th class="actions-heading">Aksi</th></tr></thead><tbody>
          <tr v-for="user in rows" :key="user.id">
            <td><div class="identity"><span>{{ user.name.slice(0, 1).toUpperCase() }}</span><div><strong>{{ user.name }}</strong><small>{{ user.email }}</small></div></div></td>
            <td><div class="primary"><strong>{{ user.role === 'pd_admin' ? 'Pengurus Daerah' : roleLabels[user.role] }}</strong><small>{{ user.role === 'pd_admin' ? user.committee?.name || 'Unit daerah belum terhubung' : roleDescriptions[user.role] }}</small></div></td>
            <td><div class="assignment-info"><strong>{{ user.role === 'pd_admin' ? 'Portal PD' : user.role === 'super_admin' || user.role === 'admin_event' ? 'Portal Admin' : `${user.active_assignments_count} assignment aktif` }}</strong><small>{{ user.role === 'pd_admin' ? 'Registrasi kontingen' : user.role === 'super_admin' ? 'Semua kewenangan' : user.role === 'admin_event' ? 'Tanpa kelola akun lain' : 'Scope cabor dan venue' }}</small></div></td>
            <td><span :class="['status-badge', user.account_status === 'verified' ? 'success' : 'danger']">{{ statusLabels[user.account_status] || user.account_status }}</span></td>
            <td>{{ formatPublicDate(user.created_at) }}</td>
            <td><div class="row-actions"><ActionIconButton icon="show" label="Lihat pengguna" @click="detailUser = user" /><ActionIconButton v-if="user.role !== 'pd_admin' && canEdit(user)" icon="edit" label="Edit pengguna" @click="openEdit(user)" /><ActionIconButton v-if="canToggleStatus(user)" icon="power" :label="user.account_status === 'verified' ? 'Nonaktifkan pengguna' : 'Aktifkan pengguna'" :tone="user.account_status === 'verified' ? 'inactive' : 'active'" @click="toggleStatus(user)" /><ActionIconButton v-if="user.role !== 'pd_admin' && canDelete(user)" icon="delete" label="Hapus pengguna" tone="danger" @click="deleteUser = user" /></div></td>
          </tr>
          <tr v-if="!rows.length"><td colspan="6" class="empty">Data pengguna tidak ditemukan.</td></tr>
        </tbody></table>
      </template>
    </AdminDataTable></section>

    <Modal :open="!!detailUser" title="Detail Pengguna" theme="light" @close="detailUser = null">
      <section v-if="detailUser" class="user-detail">
        <header><span>{{ detailUser.name.slice(0, 1).toUpperCase() }}</span><div><small>{{ detailUser.role === 'pd_admin' ? 'Pengurus Daerah' : roleLabels[detailUser.role] }}</small><h3>{{ detailUser.name }}</h3><p>{{ detailUser.email }}</p></div></header>
        <dl><div><dt>Status Login</dt><dd>{{ statusLabels[detailUser.account_status] || detailUser.account_status }}</dd></div><div><dt>Hak Akses</dt><dd>{{ detailUser.role === 'pd_admin' ? 'Portal Pengurus Daerah' : roleDescriptions[detailUser.role] }}</dd></div><div><dt>{{ detailUser.role === 'pd_admin' ? 'Unit Daerah' : 'Assignment Aktif' }}</dt><dd>{{ detailUser.role === 'pd_admin' ? detailUser.committee?.name || 'Belum terhubung' : detailUser.active_assignments_count }}</dd></div><div><dt>Tanggal Dibuat</dt><dd>{{ formatPublicDate(detailUser.created_at) }}</dd></div></dl>
        <footer><button type="button" class="outline" @click="detailUser = null">Tutup</button><button v-if="detailUser.role !== 'pd_admin' && canEdit(detailUser)" type="button" @click="detailUser = null; openEdit(detailUser)">Edit Pengguna</button></footer>
      </section>
    </Modal>

    <Modal :open="formModal" :title="editingId ? 'Edit Pengguna' : 'Tambah Pengguna'" theme="light" @close="formModal = false">
      <form class="user-form" @submit.prevent="save">
        <header><span>Akun Login</span><h3>{{ editingId ? 'Perbarui identitas dan akses' : 'Buat identitas pengguna' }}</h3><p>Kata Sandi hanya diubah bila kolom diisi saat edit.</p></header>
        <div class="fields"><label>Nama<input v-model="form.name" required /></label><label>Email<input v-model="form.email" type="email" required /></label><label class="wide">Peran<select v-model="form.role" :disabled="!isSuperAdmin || editingId === currentUser.id" required><option value="admin_event">Admin</option><option value="scorekeeper">Scorekeeper</option><option value="sport_coordinator">Koordinator Cabor</option></select></label><label v-if="editingId" class="wide">Status Login<select v-model="form.account_status" :disabled="editingId === currentUser.id" required><option value="verified">Aktif</option><option value="suspended">Nonaktif</option></select></label><PasswordField v-model="form.password" class="wide" :label="`Kata Sandi${editingId ? ' (Opsional)' : ''}`" :required="!editingId" show-strength :error="form.errors.password" /><PasswordField v-model="form.password_confirmation" class="wide" label="Ulangi Kata Sandi" :required="!editingId || !!form.password" confirmation :compare-with="form.password" :error="form.errors.password_confirmation" /></div>
        <p v-for="message in form.errors" :key="message" class="form-error">{{ message }}</p>
        <footer><button type="button" class="outline" @click="formModal = false">Batal</button><button :disabled="form.processing">{{ form.processing ? 'Menyimpan…' : editingId ? 'Simpan Perubahan' : 'Buat Pengguna' }}</button></footer>
      </form>
    </Modal>

    <Modal :open="!!deleteUser" title="Hapus Pengguna" theme="light" stacked @close="deleteUser = null">
      <section v-if="deleteUser" class="delete-user"><span aria-hidden="true">!</span><div><strong>Hapus {{ deleteUser.name }}?</strong><p>Akun akan dihapus permanen. Pengguna dengan histori aktivitas tidak dapat dihapus dan harus dinonaktifkan.</p></div><footer><button type="button" class="outline" :disabled="deleting" @click="deleteUser = null">Batal</button><button type="button" class="danger-button" :disabled="deleting" @click="remove">{{ deleting ? 'Menghapus…' : 'Hapus Pengguna' }}</button></footer></section>
    </Modal>
  </PortalLayout>
</template>

<style scoped>
.page-head{padding:8px 0 24px}.overview-card{display:grid;grid-template-columns:1.2fr 1fr;gap:28px;margin:12px 0 18px;padding:26px 28px;color:#fff;background:linear-gradient(135deg,#0b1d3d,#1946a3);border:1px solid rgba(54,194,240,.28);border-radius:16px;box-shadow:0 14px 34px rgba(7,17,38,.16)}.overview-card>div{align-content:center}.overview-card>div>span{color:#36c2f0;font-size:10px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}.overview-card h2{margin:6px 0;color:#fff;font-size:24px}.overview-card p{margin:0;color:#c7d8eb;font-size:12px;line-height:1.6}.overview-card dl{display:grid;grid-template-columns:repeat(3,1fr);margin:0;overflow:hidden;border:1px solid rgba(255,255,255,.13);border-radius:11px}.overview-card dl div{display:grid;place-content:center;padding:14px;border-right:1px solid rgba(255,255,255,.13);text-align:center;background:rgba(255,255,255,.035)}.overview-card dl div:last-child{border-right:0}.overview-card dt{color:#aac1d8;font-size:9px;font-weight:800;text-transform:uppercase}.overview-card dd{margin:5px 0 0;color:#fff;font-size:21px;font-weight:900}.operation-tabs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1px;margin-bottom:18px;padding:1px;overflow:hidden;background:#cfdce3;border:1px solid #cfdce3;border-radius:12px}.operation-tabs button{display:grid;grid-template-columns:34px 1fr;grid-template-rows:auto auto;column-gap:11px;min-height:70px;padding:13px 16px;color:#526875;background:#f7f9fa;border:0;border-radius:0;text-align:left;cursor:pointer}.operation-tabs button>span{grid-row:1/3;display:grid;place-items:center;width:34px;height:34px;align-self:center;color:#1946a3;background:#e7eef7;border:1px solid #cfdded;border-radius:8px;font-size:10px;font-weight:900}.operation-tabs button>b{align-self:end;color:#29404f;font-size:14px}.operation-tabs button>small{align-self:start;font-size:10px}.operation-tabs button.active{position:relative;color:#1946a3;background:#fff}.operation-tabs button.active::after{content:'';position:absolute;right:16px;bottom:0;left:16px;height:3px;background:#1946a3;border-radius:3px 3px 0 0}.operation-tabs button.active>span{color:#fff;background:#1946a3;border-color:#1946a3}.tab-panel{display:grid;gap:0}.panel-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:18px 20px;background:#fff;border:1px solid #d9e3e9;border-bottom:0;border-radius:14px 14px 0 0}.panel-heading>div{display:grid;gap:3px}.panel-heading span{color:#1946a3;font-size:9px;font-weight:900;letter-spacing:.12em;text-transform:uppercase}.panel-heading h3{margin:0;color:#172535;font-size:17px}.panel-heading p{margin:0;color:#71808b;font-size:11px}.panel-heading>button,.panel-heading>a{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:9px 14px;color:#fff;background:#1946a3;border:1px solid #1946a3;border-radius:7px;font-size:11px;font-weight:850;text-decoration:none;cursor:pointer}.tab-panel :deep(.admin-table-card){border-radius:0 0 14px 14px}.identity{display:flex;align-items:center;gap:11px}.identity>span{display:grid;flex:0 0 34px;place-items:center;width:34px;height:34px;color:#fff;background:#1946a3;border-radius:7px;font-size:13px;font-weight:900}.identity>div,.primary,.assignment-info{display:grid;gap:3px}.identity strong,.primary strong,.assignment-info strong{color:#173346}.identity small,.primary small,.assignment-info small{color:#71808b;font-size:10px}.actions-heading{text-align:right}.user-detail>header{display:flex;align-items:center;gap:14px;padding:22px;background:linear-gradient(135deg,#f7f9fb,#edf4fc)}.user-detail>header>span{display:grid;place-items:center;width:48px;height:48px;color:#fff;background:#1946a3;border-radius:8px;font-size:19px;font-weight:900}.user-detail header div{display:grid;gap:3px}.user-detail header small{color:#1946a3;font-size:9px;font-weight:900;text-transform:uppercase}.user-detail h3{margin:0;color:#173346;font-size:20px}.user-detail p{margin:0;color:#71808b;font-size:11px}.user-detail dl{display:grid;grid-template-columns:repeat(2,1fr);gap:1px;margin:0;background:#dce6eb;border-block:1px solid #dce6eb}.user-detail dl div{display:grid;gap:5px;padding:16px 18px;background:#fff}.user-detail dt{color:#71808b;font-size:9px;font-weight:850;text-transform:uppercase}.user-detail dd{margin:0;color:#263d4d;font-size:12px;font-weight:750}.user-detail footer,.user-form footer,.delete-user footer{display:flex;align-items:center;justify-content:flex-end;gap:10px;padding:14px 22px;background:#f8fafb;border-top:1px solid #dce6eb}.user-detail footer button,.user-form footer button,.delete-user footer button{display:inline-flex;align-items:center;justify-content:center;min-width:124px;min-height:40px;padding:9px 14px;color:#fff;background:#1946a3;border:1px solid #1946a3;border-radius:7px;font-size:11px;font-weight:850;cursor:pointer}.user-detail footer button.outline,.user-form footer button.outline,.delete-user footer button.outline{color:#536673;background:#fff;border-color:#c7d4dc}.user-detail footer button:disabled,.user-form footer button:disabled,.delete-user footer button:disabled{opacity:.55;cursor:not-allowed}.user-form>header{padding:20px 22px;background:#f7f9fb;border-bottom:1px solid #dce6eb}.user-form>header span{color:#1946a3;font-size:9px;font-weight:900;letter-spacing:.12em;text-transform:uppercase}.user-form h3{margin:4px 0;color:#173346;font-size:18px}.user-form header p{margin:0;color:#71808b;font-size:11px}.fields{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;padding:22px}.fields label{display:grid;gap:6px;color:#536673;font-size:10px;font-weight:850;text-transform:uppercase}.fields input,.fields select{width:100%;min-height:42px;padding:10px 12px;color:#172535;background:#fff;border:1px solid #c7d4dc;border-radius:7px;outline:none}.fields input:focus,.fields select:focus{border-color:#1946a3;box-shadow:0 0 0 3px rgba(25,70,163,.1)}.fields select:disabled{color:#71808b;background:#edf2f4}.form-error{margin:0 22px 10px;color:#a1432e;font-size:11px}.delete-user{display:grid;grid-template-columns:42px 1fr;gap:14px;padding:22px}.delete-user>span{display:grid;place-items:center;width:42px;height:42px;color:#fff;background:#a1432e;border-radius:8px;font-size:22px;font-weight:900}.delete-user>div{display:grid;gap:5px}.delete-user strong{color:#782b1d;font-size:15px}.delete-user p{margin:0;color:#60717f;font-size:11px;line-height:1.5}.delete-user footer{grid-column:1/-1;margin:4px -22px -22px}.delete-user footer .danger-button{color:#fff;background:#a1432e;border-color:#a1432e}@media(max-width:900px){.overview-card{grid-template-columns:1fr}.panel-heading{align-items:stretch;flex-direction:column}.overview-card dl{width:100%;min-width:0}.operation-tabs{grid-template-columns:1fr}.panel-heading>button,.panel-heading>a{width:100%}}@media(max-width:700px){.overview-card dl,.fields,.user-detail dl{grid-template-columns:1fr}.user-detail footer,.user-form footer,.delete-user footer{flex-direction:column-reverse}.user-detail footer button,.user-form footer button,.delete-user footer button{width:100%}}
.fields>.wide{grid-column:1/-1}
</style>
